async function fixture(options:Parameters<typeof checkoutFixture>[0]={}){
 const f=await checkoutFixture(options);try{
  const r=await f.prepare();assert.equal(r.response.status,201);const path='finance/checkout-requests/'+r.body.data.id,s=(await f.request(path+'/dispatch-source')).body.data;
  const a=await f.request(path+'/attempts',{sourceFingerprint:s.sourceFingerprint,expiresAt:s.draft.expiresAt,requestSha256:s.receipt.requestSha256,requestBytes:s.receipt.requestBytes});assert.equal(a.response.status,201);
  const start=await f.request(path+'/attempts/'+a.body.data.id+'/dispatch',{requestSha256:s.receipt.requestSha256,requestBytes:s.receipt.requestBytes});assert.equal(start.response.status,201);
  const database:Database={async connect(){const c=f.pg.runtime?await f.pg.runtime.connect():{query:f.pg.query.bind(f.pg),release(){}};await c.query('SET ROLE kavosh_checkout_result_worker');return c;}};
  const receipt={academyId:f.a,startId:start.body.data.id,workerId:randomUUID(),requestSha256:s.receipt.requestSha256,state:'accepted',sessionId:'cs_test_syntheticTransport',checkoutUrl:'https://checkout.stripe.com/c/pay/cs_test_syntheticTransport#private'};
  return {...f,database,receipt,path,attemptId:a.body.data.id};
 }catch(e){await f.pg.close();throw e;}
}
type Fixture=Awaited<ReturnType<typeof fixture>>;
function check(name:string,run:(f:Fixture)=>Promise<void>){test(name,async()=>{const f=await fixture();try{await run(f);}finally{await f.pg.exec('RESET ROLE');await f.pg.close();}});}
function observation(f:Fixture){return {academyId:f.a,id:randomUUID(),startId:f.receipt.startId,workerId:f.receipt.workerId,requestSha256:f.receipt.requestSha256,inspection:{state:'captured',sessionId:f.receipt.sessionId,paymentId:'pi_syntheticCaptured',chargeId:'ch_syntheticCaptured',amount:5000,currency:'cad',cardFunding:'debit',refundedAmount:0,disputed:false,paymentVerified:true,bankSettled:false,ledgerAdjusted:false}};}
async function feeObservation(f:Fixture){const principal=observation(f);await recordCheckoutProviderInspection(f.database,principal);const at=Math.floor(Date.now()/1000),fees={state:'charge_balance',sessionId:principal.inspection.sessionId,paymentId:principal.inspection.paymentId,chargeId:principal.inspection.chargeId,balanceTransactionId:'txn_syntheticFee',balanceType:'payments',providerUnitScale:2,chargeAmount:5000,chargeCurrency:'cad',grossAmount:5000,currency:'cad',feeAmount:215,netAmount:4785,createdAt:at,availableOn:at+86400,status:'pending',exchangeRate:null,reportingCategory:'charge',feeDetails:[{amount:215,currency:'cad',type:'stripe_fee',application:null}],feeBreakdownComplete:true,requiresFxReview:false,principalRequiresReview:false,bankSettled:false,ledgerAdjusted:false,feePosted:false,taxVerified:false};return {principal,input:{academyId:f.a,id:randomUUID(),startId:principal.startId,principalInspectionId:principal.id,workerId:principal.workerId,requestSha256:principal.requestSha256,fees}};}
check('fee evidence is immutable,idempotent and bound to native principal without claiming tax credit,expense or bank settlement',async f=>{
 const {input}=await feeObservation(f),r=await recordCheckoutFeeInspection(f.database,input);assert.equal(r.status,'recorded');assert.equal(r.feePosted,false);assert.equal(r.taxVerified,false);assert.equal(r.bankSettled,false);assert.equal((await recordCheckoutFeeInspection(f.database,input)).status,'duplicate');assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.checkout_balance_object_bindings')).rows[0].n,1);
 for(const patch of [{netAmount:4784},{feeAmount:216},{grossAmount:4999,netAmount:4784},{providerUnitScale:0},{feeBreakdownComplete:false}])await assert.rejects(recordCheckoutFeeInspection(f.database,{...input,id:randomUUID(),fees:{...input.fees,...patch}}),{code:'CHECKOUT_FEE_INSPECTION_UNAVAILABLE'});
 await assert.rejects(recordCheckoutFeeInspection(f.database,{...input,fees:{...input.fees,taxVerified:true}}),{code:'INVALID_CHECKOUT_FEE_INSPECTION'});assert.equal((await f.status()).received,'0.00');
 const path=f.path+'/attempts/'+f.attemptId+'/fee-inspections',list=await f.request(path+'?limit=1');assert.equal(list.response.status,200,JSON.stringify(list.body));assert.equal(list.body.data[0].feeAmount,215);assert.equal(list.body.data[0].netAmount,4785);assert.equal(list.body.data[0].providerUnitScale,2);assert.equal(list.body.data[0].feeDetails,undefined);assert.equal(list.body.feePosted,false);assert.equal((await f.request(path+'?limit=26')).response.status,400);
 const detail=await f.request(path+'/'+input.id);assert.equal(detail.response.status,200,JSON.stringify(detail.body));assert.deepEqual(detail.body.data.fees,input.fees);assert.equal(detail.body.taxVerified,false);assert.equal((await f.request(path,undefined,'foreignMaster',{academy:f.b})).response.status,404);
 await f.access('staff',{caps:['checkouts.view','invoices.view']});assert.equal((await f.request(path,undefined,'staff')).response.status,200);await f.access('staff',{caps:['checkouts.view']});assert.equal((await f.request(path+'/'+input.id,undefined,'staff')).response.status,403);
 await f.pg.exec('SET ROLE kavosh_runtime');try{await f.pg.query("SELECT set_config('app.academy_id',$1,false)",[f.b]);assert.equal((await f.pg.query('SELECT * FROM public.checkout_fee_inspections')).rows.length,0);await assert.rejects(f.pg.exec('DELETE FROM public.checkout_fee_inspections'),/permission denied/);await assert.rejects(f.pg.exec('SELECT public.record_checkout_fee_inspection(NULL,NULL,NULL,NULL,NULL,NULL,NULL)'),/permission denied/);}finally{await f.pg.exec('RESET ROLE');}
});
