 const course=await f.made('courses',{code:'CREDITNEXT',name:'Next course'}),cl=await f.made('classes',{hubId:f.hub,courseId:course.id,courseVersion:1,name:'Next credit class',mode:'in_person',schedule:{oneOff:[{start:'2027-02-05T10:00',end:'2027-02-05T11:00',disambiguation:'reject'}]}}),enrollment=await f.made('classes/'+cl.id+'/enrollments',{studentId:student.id,studentProfileVersion:1,joinsOn:'2027-01-01',reason:'Synthetic next enrollment'});
 let currency=f.currency,accounts=f.base.accounts;if(options.usd){currency=await f.made('finance/currencies',{code:'USD',name:'US dollar',unitScale:2,reason:'Synthetic other currency'});const create=(code:string,kind:string,operationalRole:string)=>f.made('finance/accounts',{code,name:'USD '+code,kind,operationalRole,hubId:f.hub,currencyId:currency.id,currencyVersion:1,reason:'Synthetic other currency account'}),ar=await create('USDAR','asset','receivable'),deferred=await create('USDDEFERRED','liability','deferred_revenue'),tax=await create('USDTAX','liability','tax_payable');accounts={receivable:{id:ar.id,version:1},consideration:{id:deferred.id,version:1},tax:{id:tax.id,version:1}};}
 const plan=await f.made('enrollments/'+enrollment.id+'/tuition-plan',{...f.planInput,currencyId:currency.id,currencyVersion:1,supplyOn:'2027-02-05'}),r=await f.request('finance/tuition-plans/'+plan.id+'/invoice',{...f.base,billToId:student.id,accounts});assert.equal(r.response.status,201,JSON.stringify(r.body));return {invoice:r.body.data,cl};
