check('same-customer credit can pay another class;denied target classes are filtered before history pagination',async f=>{
 const c=await creditApplication(f),next=await anotherCreditInvoice(f),r=await f.request(c.path,{...c.input,invoiceId:next.invoice.id});assert.equal(r.response.status,201,JSON.stringify(r.body));assert.equal((await f.status()).balance,'113.00');assert.equal((await f.request('finance/invoices/'+next.invoice.id+'/payment-status')).body.data.balance,'63.00');
 const base=await f.access('staff',{all:false,studentId:f.student.id,caps:['receipts.view','checkouts.view','invoices.view']}),history=()=>f.request(c.path+'?limit=1',undefined,'staff');assert.equal((await history()).body.data.length,1);
 const deny=await f.made('roles',{name:'Deny next credit class',permissions:[{capability:'receipts.view',effect:'deny'}]}),path='people/'+f.actors.staff.person+'/access',old=await f.request(path);assert.equal((await f.request(path,{expectedVersion:old.body.data.version,assignments:[{roleId:base.id,allHubs:false,personIds:[f.student.id]},{roleId:deny.id,allHubs:false,classIds:[next.cl.id]}]})).response.status,200);
 const hidden=await history();assert.equal(hidden.response.status,200,JSON.stringify(hidden.body));assert.deepEqual(hidden.body.data,[]);assert.equal(hidden.body.nextCursor,null);assert.doesNotMatch(JSON.stringify(hidden.body),new RegExp(next.invoice.id+'|'+r.body.data.id));
});
